다음은 AgentVoiceInput.cs의 현재 결과 적용과 취소 생명주기 전체입니다. 전송은 별도 Send 메서드에서만 처리합니다.

```csharp
private IEnumerator Recognize(byte[] wave, int version)
{
    yield return null;
    yield return _link.Transcribe(wave, (success, text, milliseconds) =>
    {
        if (version != _requestVersion || !IsVoiceMode || _panel.Selected?.CompanionId != _companionId)
        {
            return;
        }
        if (success)
        {
            _review.text = text;
            _status.text = "인식 " + milliseconds.ToString("F0") + "ms · 문장을 확인하고 보내기를 눌러 주세요.";
        }
        else
        {
            _status.text = text;
        }
    });
    _recognition = null;
    _record.interactable = true;
}
```

```csharp
public void Cancel()
{
    _requestVersion++;
    if (_clip != null)
    {
        Microphone.End(null);
        Destroy(_clip);
        _clip = null;
    }
    if (_recognition != null)
    {
        StopCoroutine(_recognition);
        _recognition = null;
    }
    _link.CancelSpeech();
    _review.text = string.Empty;
    _record.interactable = true;
    _stop.interactable = false;
    _status.text = "녹음하지 않는 중 · 녹음 시작 버튼을 눌러 주세요.";
}
```

```mermaid
flowchart TD
 A[모드 변경 또는 동료 변경 또는 취소] --> B[요청 버전 증가]
 B --> C[마이크 종료와 메모리 해제]
 C --> D[진행 코루틴과 HTTP 취소]
 D --> E[이전 검토 문장 폐기]
 E --> F[다른 동료에 늦은 결과 적용 금지]
```

